
import json
import sys
from pathlib import Path
from datetime import datetime, timezone


def load_evidence(path):
    """Load and validate evidence generated by the C engine."""
    with path.open("r", encoding="utf-8") as file:
        data = json.load(file)

    required = {"summary", "failure_codes", "anomalies"}
    missing = required - data.keys()

    if missing:
        raise ValueError(
            f"Missing required fields: {sorted(missing)}"
        )

    summary = data["summary"]

    for field in (
        "total_calls",
        "successful_calls",
        "failed_calls",
        "failure_rate_percent",
    ):
        if field not in summary:
            raise ValueError(f"Summary is missing field: {field}")

    if not isinstance(data["failure_codes"], list):
        raise ValueError("'failure_codes' must be a list")

    if not isinstance(data["anomalies"], list):
        raise ValueError("'anomalies' must be a list")

    return data


def investigate(data):
    """Generate explainable, rule-based investigation findings."""
    summary = data["summary"]
    failures = data["failure_codes"]
    anomalies = data["anomalies"]

    total = summary["total_calls"]
    failed = summary["failed_calls"]
    rate = summary["failure_rate_percent"]

    evidence = [
        f"{failed} of {total} calls failed ({rate:.2f}%)."
    ]
    hypotheses = []
    checks = []

    # Analyze recorded failure codes.
    if failures:
        ranked = sorted(
            failures,
            key=lambda item: item.get("count", 0),
            reverse=True,
        )

        dominant = ranked[0]
        dominant_code = dominant.get("code", "UNKNOWN")
        dominant_count = dominant.get("count", 0)

        evidence.append(
            f"Most frequent failure code: {dominant_code} "
            f"({dominant_count} occurrences)."
        )

        if dominant_code == "NETWORK_TIMEOUT":
            hypotheses.append({
                "hypothesis": (
                    f"{dominant_code} failures may be caused by "
                    "network latency, packet loss, an unavailable "
                    "upstream service, or a short timeout setting."
                ),
                "confidence": "medium",
                "status": "unconfirmed",
                "reasoning": (
                    f"The logs record {dominant_count} occurrences "
                    f"of {dominant_code}. These support further "
                    "investigation but do not establish the "
                    "underlying cause."
                ),
            })

            checks.extend([
                {
                    "priority": "high",
                    "check": "Inspect request and response latency",
                    "purpose": (
                        "Compare failed-call latency with successful "
                        "calls and the configured timeout."
                    ),
                },
                {
                    "priority": "high",
                    "check": "Check network and upstream service health",
                    "purpose": (
                        "Review packet loss, connection errors, "
                        "and upstream service logs."
                    ),
                },
                {
                    "priority": "medium",
                    "check": "Review timeout configuration",
                    "purpose": (
                        "Verify timeout values against expected "
                        "service response times."
                    ),
                },
            ])

        else:
            hypotheses.append({
                "hypothesis": (
                    f"The failures are associated with {dominant_code}."
                ),
                "confidence": "low",
                "status": "unconfirmed",
                "reasoning": (
                    "The failure code indicates a symptom, not "
                    "proof of the underlying root cause."
                ),
            })

            checks.append({
                "priority": "high",
                "check": f"Investigate failure code {dominant_code}",
                "purpose": (
                    "Review application logs and service documentation."
                ),
            })

    else:
        evidence.append("No failure codes were recorded.")

    # Analyze detected time-window anomalies.
    for anomaly in anomalies:
        start = anomaly.get("window_start", "unknown")
        window_total = anomaly.get("total_calls", 0)
        window_failed = anomaly.get("failed_calls", 0)
        window_rate = anomaly.get("failure_rate_percent", 0.0)

        evidence.append(
            f"Flagged window {start}: {window_failed}/{window_total} "
            f"calls failed ({window_rate:.2f}%)."
        )

        hypotheses.append({
            "hypothesis": (
                "A localized service or network degradation may "
                "explain the elevated failure rate in this window."
            ),
            "confidence": "medium",
            "status": "unconfirmed",
            "reasoning": (
                "An elevated failure rate was detected. Correlated "
                "telemetry is needed to identify its cause."
            ),
        })

    if anomalies:
        checks.append({
            "priority": "high",
            "check": "Correlate the flagged window with system metrics",
            "purpose": (
                "Compare network latency, CPU, memory, service errors, "
                "and deployment events during the window."
            ),
        })

    if not checks:
        checks.append({
            "priority": "medium",
            "check": "Collect additional diagnostic telemetry",
            "purpose": (
                "Gather latency, service health, and application logs."
            ),
        })

    return {
        "report_type": "mock_ai_network_investigation",
        "generated_at_utc": datetime.now(timezone.utc).isoformat(),
        "source": data.get("source", "unknown"),
        "summary": summary,
        "observed_evidence": evidence,
        "root_cause_hypotheses": hypotheses,
        "recommended_diagnostic_checks": checks,
        "limitations": [
            "This is a deterministic, rule-based mock investigator.",
            "Hypotheses are not confirmed root causes.",
            "Only the supplied call-log evidence was analyzed.",
            "No live network or external telemetry checks were performed.",
        ],
    }


def main():
    if len(sys.argv) != 3:
        print(
            "Usage: python mock_ai.py <evidence.json> <report.json>",
            file=sys.stderr,
        )
        return 2

    input_path = Path(sys.argv[1])
    output_path = Path(sys.argv[2])

    try:
        data = load_evidence(input_path)
        report = investigate(data)

        output_path.parent.mkdir(parents=True, exist_ok=True)

        with output_path.open("w", encoding="utf-8") as file:
            json.dump(report, file, indent=4, ensure_ascii=False)
            file.write("\n")

        print(f"Investigation report written to: {output_path}")

        print("\nObserved evidence:")
        for item in report["observed_evidence"]:
            print(f"- {item}")

        print("\nRoot-cause hypotheses:")
        for item in report["root_cause_hypotheses"]:
            print(f"- [{item['confidence']}] {item['hypothesis']}")
            print(f"  Status: {item['status']}")

        print("\nRecommended diagnostic checks:")
        for item in report["recommended_diagnostic_checks"]:
            print(f"- [{item['priority']}] {item['check']}")
            print(f"  Purpose: {item['purpose']}")

        return 0

    except (
        OSError,
        json.JSONDecodeError,
        ValueError,
        TypeError,
    ) as exc:
        print(f"Investigation failed: {exc}", file=sys.stderr)
        return 1


if __name__ == "__main__":
    raise SystemExit(main())
